// Responsive WebP versions of every photo live next to it: name-480.webp, name-800.webp, name-1280.webp
// (generated by scripts/images.py). Phones download the small one.
export const WIDTHS = [480, 800, 1280] as const;
export const srcset = (name: string) => WIDTHS.map((w) => `img/${name}-${w}.webp ${w}w`).join(', ');
